// T1561b — the sentinel's body: the kit's robot frame, set down in the tunnel.
struct Params {
  travel: f32, // @default 0  Distance travelled along the tunnel, metres.
  offset: vec3f, // @default 0  The robot's place off the tunnel's axis: right, up, ahead (metres).
  roll: f32, // @default 0  Roll about its own heading, radians.
};
// T1561b — the tunnel's centreline (generated by src/projects/sentinel-bot/path.ts).
const PATH_PERIOD: f32 = 960.0;

fn pathAt(z: f32) -> vec3f {
  return vec3f(14.0 * sin(0.0327249235 * z + 0.4) + 5.0 * sin(0.085084801 * z + 1.9), 6.0 * sin(0.0261799388 * z + 2.2) + 2.5 * sin(0.0719948316 * z + 0.7), z);
}

fn pathTangent(z: f32) -> vec3f {
  return normalize(vec3f(0.458148929 * cos(0.0327249235 * z + 0.4) + 0.425424005 * cos(0.085084801 * z + 1.9), 0.157079633 * cos(0.0261799388 * z + 2.2) + 0.179987079 * cos(0.0719948316 * z + 0.7), 1.0));
}

struct Frame {
  origin: vec3f,
  right: vec3f,
  up: vec3f,
  forward: vec3f,
};

fn pathFrame(z: f32) -> Frame {
  var frame: Frame;
  frame.origin = pathAt(z);
  frame.forward = pathTangent(z);
  frame.right = normalize(cross(vec3f(0.0, 1.0, 0.0), frame.forward));
  frame.up = cross(frame.forward, frame.right);
  return frame;
}

// The robot's own frame: on the tunnel's frame at its distance, facing a little way ahead so it
// turns into a bend before it reaches it, banking into the bend, and never hanging dead still.
fn robotFrame(travel: f32, offset: vec3f, roll: f32, time: f32) -> Frame {
  let z = travel + offset.z;
  let tunnel = pathFrame(z);
  var frame: Frame;
  let drift = vec2f(sin(time * 0.9 + offset.z), sin(time * 1.3 + offset.z * 1.7)) * 0.05;
  frame.origin = tunnel.origin + tunnel.right * (offset.x + drift.x) + tunnel.up * (offset.y + drift.y);
  frame.forward = pathTangent(z + 1.2);
  let right = normalize(cross(vec3f(0.0, 1.0, 0.0), frame.forward));
  let up = cross(frame.forward, right);
  // How fast the heading swings, measured a couple of metres either side: the inside of the turn drops.
  let bank = roll - 1.5 * (pathTangent(z + 2.0).x - pathTangent(z - 2.0).x);
  frame.right = right * cos(bank) + up * sin(bank);
  frame.up = up * cos(bank) - right * sin(bank);
  return frame;
}

fn process(p: Point, ctx: PointCtx) -> Point {
  var q = p;
  let frame = robotFrame(ctx.params.travel, ctx.params.offset, ctx.params.roll, ctx.absTime);
  q.position = frame.origin + frame.right * p.position.x + frame.up * p.position.y + frame.forward * p.position.z;
  q.normal = normalize(frame.right * p.normal.x + frame.up * p.normal.y + frame.forward * p.normal.z);
  return q;
}

parameters.defaults:
bar = floor(abstime / 4);
value = 0;
shot = 0;
cuts = 0;
distance = 7.5;
viewX = 1.1;
viewY = 0.6

parameters.expressions:
turn = floor(bar / 2);
pick = (cuts > 0.5) * (turn - 5 * floor(turn / 5)) + (cuts <= 0.5) * floor(shot + 0.5);
post = (floor(value / 25.6) + 0.5) * 25.6;
ahead = (pick == 0) * (0 - distance) + (pick == 1) * 5.5 + (pick == 2) * 0.4 + (pick == 3) * (post - value) + (pick == 4) * 1.5 * sin(abstime * 0.17);
right = (pick == 0) * viewX + (pick == 1) * (0 - 0.9) + (pick == 2) * 2 + (pick == 3) * 1.6 + (pick == 4) * 1.9 * cos(abstime * 0.3);
up = (pick == 0) * viewY + (pick == 1) * 0.35 + (pick == 2) * 0.15 + (pick == 3) * (0 - 1.3) + (pick == 4) * 1.3 * sin(abstime * 0.3);
lens = (pick == 0) * 55 + (pick == 1) * 48 + (pick == 2) * 68 + (pick == 3) * 40 + (pick == 4) * 60;
z = value + ahead

